import fs from 'node:fs/promises'; import path from 'node:path'; import {digest} from '../evidence/index.mjs';
export class ResearchCache {constructor(dir){this.dir=dir;} file(url){return path.join(this.dir,digest(url)+'.json');} async get(url,maxAgeDays){try{const item=JSON.parse(await fs.readFile(this.file(url),'utf8'));return Date.now()-Date.parse(item.accessed_at)<maxAgeDays*864e5?item:null;}catch{return null;}} async put(url,item){await fs.mkdir(this.dir,{recursive:true});await fs.writeFile(this.file(url),JSON.stringify({...item,accessed_at:new Date().toISOString()}));}}
